function validate([a, b]) {
  if (typeof a !== 'string' || a.length < 1 || a.length > 10000) return 'a has 1 to 10000 letters.';
  if (typeof b !== 'string' || b.length < 1 || b.length > 10000) return 'b has 1 to 10000 letters.';
  if (!/^[a-z]+$/.test(a) || !/^[a-z]+$/.test(b)) return 'Both strings use lowercase English letters only.';
  return null;
}

