function repeatedStringMatch(a, b) {
  const failure = new Array(b.length).fill(0);
  let length = 0;
  for (let i = 1; i < b.length; i++) {
    while (length > 0 && b[i] !== b[length]) {
      length = failure[length - 1];
    }
    if (b[i] === b[length]) {
      length++;
    }
    failure[i] = length;
  }

  const limit = a.length + b.length;
  let matched = 0;
  for (let i = 0; i < limit; i++) {
    const ch = a[i % a.length];
    while (matched > 0 && ch !== b[matched]) {
      matched = failure[matched - 1];
    }
    if (ch === b[matched]) {
      matched++;
    }
    if (matched === b.length) {
      return Math.ceil((i + 1) / a.length);
    }
  }
  return -1;
}

