function generate(rand, size) {
  const large = size === 'large';
  const letters = 'abc'.slice(0, 1 + Math.floor(rand() * 3));
  const word = (len) => Array.from({ length: len }, () => letters[Math.floor(rand() * letters.length)]).join('');
  const a = word(large ? 1 + Math.floor(rand() * 3000) : 1 + Math.floor(rand() * 4));
  const want = large ? 1 + Math.floor(rand() * 10000) : 1 + Math.floor(rand() * 10);
  if (rand() < 0.3) return [a, word(want)];
  // Usually cut b out of the endless repetition of a, sometimes with one letter changed.
  const start = Math.floor(rand() * a.length);
  const chars = Array.from({ length: want }, (_, i) => a[(start + i) % a.length]);
  if (rand() < 0.3) chars[Math.floor(rand() * want)] = 'abcd'[Math.floor(rand() * 4)];
  return [a, chars.join('')];
}
